import * as fs from 'node:fs';
import * as path from 'node:path';
import { debugLogger } from './debugLogger.js';

const LOG_FILE_NAME = 'rag-trace.log';

/**
 * A secure logger for recording RAG trace data to a local file.
 *
 * Trace entries are appended as JSON lines to `rag-trace.log`. Both the log
 * directory and file are created and maintained with strict owner-only
 * permissions (0o700 / 0o600) to protect potentially sensitive data.
 */
export class RagLogger {
  private logsDir: string | undefined;
  private permissionsEnforced = false;

  /**
   * Initializes the logger with a directory path, creating the directory with
   * owner-only permissions.
   */
  initialize(logsDir: string): void {
    try {
      fs.mkdirSync(logsDir, { recursive: true, mode: 0o700 });
      const realPath = fs.realpathSync(logsDir);
      fs.chmodSync(realPath, 0o700);
      this.logsDir = realPath;
      this.permissionsEnforced = false;
    } catch (error) {
      debugLogger.error(
        'Failed to create or set permissions for rag-trace.log directory',
        error,
      );
    }
  }

  /**
   * Appends a structured trace entry to the log file as a JSON line.
   */
  log(entry: {
    sessionId: string;
    ragStatus: string;
    snippets: Array<{ content: string; relevanceScore?: number }>;
  }): void {
    if (this.logsDir === undefined) {
      debugLogger.warn('RagLogger was called before being initialized.');
      return;
    }

    const filePath = path.join(this.logsDir, LOG_FILE_NAME);
    try {
      const fd = fs.openSync(filePath, 'a', 0o600);
      try {
        if (!this.permissionsEnforced) {
          fs.fchmodSync(fd, 0o600);
          this.permissionsEnforced = true;
        }
        fs.writeSync(
          fd,
          JSON.stringify({ timestamp: new Date().toISOString(), ...entry }) +
            '\n',
          null,
          'utf8',
        );
      } finally {
        fs.closeSync(fd);
      }
    } catch (error) {
      debugLogger.error(
        `Failed to write to ${path.join(this.logsDir, LOG_FILE_NAME)}`,
        error,
      );
    }
  }
}
